<?php declare(strict_types=1); ?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sayfa düzenle</title><style>body{font-family:system-ui;background:#f5f7f5;color:#26332b;margin:0}.wrap{max-width:850px;margin:35px auto;padding:0 18px}.panel{background:white;padding:24px;border-radius:14px}label{display:block;margin:15px 0;font-weight:700;font-size:13px}input,textarea,select{display:block;width:100%;box-sizing:border-box;padding:12px;border:1px solid #dfe6e0;border-radius:8px;margin-top:6px;font:inherit}textarea{min-height:300px}.btn{background:#176b50;color:white;border:0;padding:13px 18px;border-radius:8px;font-weight:700}
/* Consistent admin links and actions */
a{color:#176b50;text-decoration:none;transition:color .18s ease,background-color .18s ease,border-color .18s ease}a:hover{color:#104c39;text-decoration:none}td a:not([class]),.table-wrap a:not([class]){display:inline-flex;align-items:center;justify-content:center;padding:7px 11px;border:1px solid #dce9e0;border-radius:8px;background:#f5faf6;color:#176b50;font-size:12px;font-weight:750;white-space:nowrap}td a:not([class]):hover,.table-wrap a:not([class]):hover{background:#eaf4ee;border-color:#b9d8c4}button,input[type=submit]{cursor:pointer;font:inherit}button{transition:filter .18s ease,transform .18s ease}button:hover,input[type=submit]:hover{filter:brightness(.96)}
</style></head><body><main class="wrap"><h1><?= !empty($page['id'])?'Sayfayı düzenle':'Yeni sayfa' ?></h1><?php if(!empty($page['id'])): ?><p><a href="<?= e(app_url('/admin/pages/layout?page=page:'.(int)$page['id'].'&lang='.rawurlencode($locale))) ?>">Edit page layout and widgets</a></p><?php endif; ?><form method="post" action="/admin/pages/save"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)($page['id']??0) ?>"><?php if(!empty($page['id'])): ?><input type="hidden" name="language_code" value="<?= e($locale) ?>"><?php endif; ?><section class="panel"><?php if(!empty($page['id'])): ?><label>İçerik dili<input value="<?= e($locale) ?>" disabled></label><?php else: ?><label>İçerik dili<select name="language_code" required><?php foreach($languages as $language): ?><option value="<?= e($language['code']) ?>" <?= $language['code']===$locale?'selected':'' ?>><?= e($language['name']) ?> (<?= e($language['code']) ?>)</option><?php endforeach; ?></select></label><?php endif; ?><label>Sayfa başlığı<input name="title" required maxlength="220" value="<?= e($page['title']??'') ?>"></label><label>URL kısa adı<input name="slug" required maxlength="240" value="<?= e($page['slug']??'') ?>"></label><label>Yayın durumu<select name="status"><option value="draft" <?= ($page['status']??'draft')==='draft'?'selected':'' ?>>Taslak</option><option value="published" <?= ($page['status']??'')==='published'?'selected':'' ?>>Yayında</option></select></label><label>SEO başlığı<input name="meta_title" maxlength="220" value="<?= e($page['meta_title']??'') ?>"></label><label>SEO açıklaması<input name="meta_description" maxlength="320" value="<?= e($page['meta_description']??'') ?>"></label><label>Odak anahtar kelime<input name="focus_keyword" maxlength="120" value="<?= e($page['focus_keyword']??'') ?>" placeholder="Örn. Kaş kiralık villa"></label><label>Optional legacy text content<textarea name="content"><?= e($page['content']??'') ?></textarea></label><?php include dirname(__DIR__,2) . '/partials/seo-analyzer.php'; ?><button class="btn">Kaydet</button></section></form><p><a href="/admin/pages?lang=<?= e(rawurlencode($locale)) ?>">Sayfalara dön</a></p></main></body></html>